"""A perceptron from scratch: learn AND and OR, fail on XOR, learn two iris species, then solve XOR with two layers."""

import numpy as np
from sklearn.datasets import load_iris


def step(z):
    """The Heaviside step function: 1 where z >= 0, otherwise 0."""
    return (np.asarray(z) >= 0).astype(int)


class Perceptron:
    def __init__(self, n_inputs, learning_rate=1.0):
        self.w = np.zeros(n_inputs)
        self.b = 0.0
        self.lr = learning_rate

    def predict(self, X):
        # TODO: return the step function of the weighted sum, X @ self.w + self.b
        return np.zeros(len(X), dtype=int)

    def fit(self, X, y, max_epochs=20):
        """Apply the perceptron rule one example at a time, for up to max_epochs passes over the data.
        Stop after a pass with no mistakes. Return the number of mistakes in each pass."""
        history = []
        for epoch in range(1, max_epochs + 1):
            mistakes = 0
            for xi, target in zip(X, y):
                # TODO: predict this example; if the prediction is wrong, count a mistake and update:
                #      error = target - prediction
                #      self.w += self.lr * error * xi
                #      self.b += self.lr * error
                pass
            history.append(mistakes)
            if mistakes == 0:
                break
        return history


def report(name, model, X, y, history):
    accuracy = (model.predict(X) == y).mean()
    if history[-1] == 0:
        outcome = f"converged in epoch {len(history)}"
    else:
        outcome = f"no convergence in {len(history)} epochs"
    print(f"{name}: {outcome}; mistakes per epoch {history}")
    print(f"    weights {np.round(model.w, 3)}, bias {model.b:.3f}, accuracy {accuracy:.2f}")


def two_layer_xor(X):
    """XOR = AND(OR(x1, x2), NAND(x1, x2)): two perceptrons in a hidden layer, one in the output layer."""
    # TODO: build it from three perceptrons with weights and biases you choose by hand:
    #      h_or   = step(X @ w_or + b_or)            1 when at least one input is 1
    #      h_nand = step(X @ w_nand + b_nand)        1 unless both inputs are 1
    #      output = step(h_or * w1 + h_nand * w2 + b) 1 only when both hidden units are 1
    return np.zeros(len(X), dtype=int)


def main():
    X = np.array([[0, 0], [0, 1], [1, 0], [1, 1]])
    gates = {"AND": np.array([0, 0, 0, 1]), "OR": np.array([0, 1, 1, 1]), "XOR": np.array([0, 1, 1, 0])}
    for name, y in gates.items():
        model = Perceptron(n_inputs=2)
        report(name, model, X, y, model.fit(X, y))

    iris = load_iris()
    petals = iris.data[:, 2:4]  # petal length and petal width, in cm
    for a, b in [(0, 1), (1, 2)]:
        mask = (iris.target == a) | (iris.target == b)
        Xi, yi = petals[mask], (iris.target[mask] == b).astype(int)
        Xi = (Xi - Xi.mean(axis=0)) / Xi.std(axis=0)  # standardise: mean 0, standard deviation 1
        model = Perceptron(n_inputs=2)
        report(f"iris {iris.target_names[a]} vs {iris.target_names[b]}", model, Xi, yi, model.fit(Xi, yi))

    print("Two-layer network on XOR:", two_layer_xor(X), "expected", gates["XOR"])


if __name__ == "__main__":
    main()

